export const meta = {
  name: 'Warden I',
  rationale: 'You hide in the bottom-left pocket, so I keep a quiet lane there and only fire when you are still far enough away to matter.',
  version: 2,
};

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

function hypot2(dx, dy) {
  return Math.sqrt(dx * dx + dy * dy);
}

function norm(dx, dy) {
  const d = hypot2(dx, dy);
  if (!(d > 0)) return [0, 0];
  return [dx / d, dy / d];
}

function heatTarget(view) {
  const heat = view && view.history && view.history.playerPosHeat;
  let best = 56;
  let bestV = -1;
  if (heat && heat.length >= 64) {
    for (let i = 48; i < 64; i++) {
      const v = heat[i];
      if (v > bestV) {
        bestV = v;
        best = i;
      }
    }
  }
  const col = best % 8;
  const row = (best / 8) | 0;
  return { x: col * 100 + 50, y: row * 100 + 50 };
}

export function init() {
  return {
    lastAttack: -9999,
    roam: 0,
  };
}

export function decide(view, mem) {
  const bx = view.boss.x;
  const by = view.boss.y;
  const px = view.player.x;
  const py = view.player.y;

  const dx = px - bx;
  const dy = py - by;
  const dist = hypot2(dx, dy);

  const target = heatTarget(view);
  const tx = clamp(target.x, 60, 260);
  const ty = clamp(target.y, 620, 790);

  const readyBurst = view.boss.cooldowns.burst <= 0;
  const quiet = view.tick - (mem.lastAttack | 0);

  // Stay near the pocket they lived in, but never rush contact.
  if (dist < 170) {
    const away = norm(bx - px, by - py);
    const mx = clamp(bx + away[0] * 42, 40, 760);
    const my = clamp(by + away[1] * 42, 40, 760);
    mem.roam = (mem.roam + 1) | 0;
    return { type: 'move', dx: mx - bx, dy: my - by };
  }

  // Long-range only: a small burst into the lane they keep returning to.
  if (readyBurst && quiet >= 120 && dist > 260) {
    mem.lastAttack = view.tick;
    const ang = Math.atan2(dy, dx);
    return { type: 'burst', angle: ang, count: 3 };
  }

  // Reposition toward the hot pocket, then settle.
  const moveX = tx - bx;
  const moveY = ty - by;

  // If already close enough to the pocket, hold a quiet stance.
  if (Math.abs(moveX) + Math.abs(moveY) < 18) {
    return { type: 'idle' };
  }

  return { type: 'move', dx: moveX * 0.35, dy: moveY * 0.35 };
}

