export const meta = {
  name: 'Pocket Warden II',
  rationale: 'You camp the bottom-left pocket, so I put two pressures there and make the safe window keep ending.',
  version: 2,
};

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

function dist2(ax, ay, bx, by) {
  const dx = ax - bx;
  const dy = ay - by;
  return dx * dx + dy * dy;
}

function pickHeatTarget(view) {
  // Bottom-left weighted focus: the cells you lived in most.
  const w = view.arena.w;
  const h = view.arena.h;
  let sx = 0, sy = 0, sw = 0;

  const heat = view.history && view.history.playerPosHeat;
  if (heat && heat.length) {
    for (let i = 0; i < heat.length; i++) {
      const wt = heat[i] || 0;
      if (!wt) continue;
      const cx = ((i % 8) + 0.5) * (w / 8);
      const cy = (Math.floor(i / 8) + 0.5) * (h / 8);
      sx += cx * wt;
      sy += cy * wt;
      sw += wt;
    }
  }

  if (sw > 0) return { x: sx / sw, y: sy / sw };
  return { x: 150, y: 730 };
}

function angleTo(ax, ay, bx, by) {
  return Math.atan2(by - ay, bx - ax);
}

export function init() {
  return {
    nextAttackAt: 0,
    nextSpawnAt: 60,
    lastMode: 0,
  };
}

export function decide(view, mem) {
  const t = view.tick | 0;
  const bx = view.boss.x;
  const by = view.boss.y;
  const px = view.player.x;
  const py = view.player.y;

  const target = pickHeatTarget(view);
  const d2 = dist2(bx, by, px, py);
  const close = d2 < 220 * 220;
  const mid = d2 < 360 * 360;

  // Keep pressure pointed at the pocket you actually used.
  if (t >= mem.nextSpawnAt && view.boss.cooldowns.spawn <= 0) {
    mem.nextSpawnAt = t + 420 + ((rand() * 60) | 0);
    if (rand() < 0.65) {
      return { type: 'spawn', x: clamp(target.x + (rand() * 80 - 40), 20, 780), y: clamp(target.y + (rand() * 50 - 25), 20, 780) };
    }
  }

  // Measured signature punish: only some approaches get the full answer.
  if (t >= mem.nextAttackAt) {
    const readyBurst = view.boss.cooldowns.burst <= 0;
    const readyCharge = view.boss.cooldowns.charge <= 0;
    const readySlam = view.boss.cooldowns.slam <= 0;

    // If you're anchored in the pocket, the floor is not safe.
    if ((close || (px < 300 && py > 600)) && readyBurst && rand() < 0.5) {
      mem.nextAttackAt = t + 34;
      return { type: 'burst', angle: angleTo(bx, by, px, py), count: 8 };
    }

    // Catch the stationary return path with occasional slam.
    if (readySlam && (close || (px < 280 && py > 620)) && rand() < 0.35) {
      mem.nextAttackAt = t + 52;
      return { type: 'slam', x: clamp(px + (rand() * 50 - 25), 40, 760), y: clamp(py + (rand() * 50 - 25), 40, 760) };
    }

    // If you're farther out, close once, then reset.
    if (mid && readyCharge && rand() < 0.45) {
      mem.nextAttackAt = t + 28;
      return { type: 'charge', angle: angleTo(bx, by, px, py) };
    }
  }

  // Gentle steering: move toward the hotspot, but not relentlessly.
  const dx = clamp(target.x - bx, -18, 18);
  const dy = clamp(target.y - by, -18, 18);

  if ((t & 7) !== 0) {
    return { type: 'move', dx, dy };
  }

  // Quiet beat: let the player think they got a reset.
  return { type: 'idle' };
}

