export const meta = {
  name: 'Warden III',
  rationale: 'You live in the lower-left pocket, so I keep flooding that corner until your safe window breaks.',
  version: 2,
};

function clamp(v, a, b) {
  return v < a ? a : v > b ? b : v;
}

function len(x, y) {
  return Math.sqrt(x * x + y * y);
}

function norm(x, y) {
  var d = len(x, y);
  if (!(d > 0)) return { x: 0, y: 0 };
  return { x: x / d, y: y / d };
}

function dist2(ax, ay, bx, by) {
  var dx = ax - bx, dy = ay - by;
  return dx * dx + dy * dy;
}

function chooseHeatTarget(view) {
  // Focus the bottom-left pocket the player inhabited most.
  var hx = 125, hy = 725;
  if (view.history && view.history.playerPosHeat && view.history.playerPosHeat.length >= 64) {
    var best = 0, bi = 0;
    for (var i = 0; i < 64; i++) {
      var v = view.history.playerPosHeat[i] || 0;
      if (v > best) { best = v; bi = i; }
    }
    var cellW = view.arena.w / 8;
    var cellH = view.arena.h / 8;
    hx = (bi % 8 + 0.5) * cellW;
    hy = (Math.floor(bi / 8) + 0.5) * cellH;
  }
  if (hx > 300 || hy < 600) { hx = 125; hy = 725; }
  return { x: hx, y: hy };
}

function ready(cd) {
  return !(cd > 0);
}

export function init() {
  return {
    phase: 0,
    drift: 1,
    bias: 0.5,
  };
}

export function decide(view, mem) {
  var bx = view.boss.x, by = view.boss.y;
  var px = view.player.x, py = view.player.y;

  var cds = view.boss.cooldowns || {};
  var canSpawn = ready(cds.spawn);
  var canBurst = ready(cds.burst);
  var canCharge = ready(cds.charge);
  var canSlam = ready(cds.slam);

  var target = chooseHeatTarget(view);

  var inPocket = (px <= 260 && py >= 620);
  var close = dist2(bx, by, px, py) < 180 * 180;
  var veryClose = dist2(bx, by, px, py) < 90 * 90;

  // Three pressure sources: spawn, zone burst, and closing slam/charge.
  if (canSpawn && mem.phase < 2 && rand() < 0.92) {
    mem.phase += 1;
    return { type: 'spawn', x: target.x + (rand() * 60 - 30), y: target.y + (rand() * 50 - 25) };
  }

  if (canBurst && (veryClose || (inPocket && rand() < 0.85))) {
    mem.phase += 1;
    var dx = px - bx, dy = py - by;
    var a = Math.atan2(dy, dx);
    if (!isFinite(a)) a = 0;
    return { type: 'burst', angle: a, count: 8 };
  }

  if (canSlam && (inPocket || (close && rand() < 0.65))) {
    mem.phase += 1;
    return { type: 'slam', x: target.x, y: target.y };
  }

  if (canCharge && (close || (inPocket && rand() < 0.55))) {
    mem.phase += 1;
    var dx2 = target.x - bx, dy2 = target.y - by;
    var a2 = Math.atan2(dy2, dx2);
    if (!isFinite(a2)) a2 = 0;
    return { type: 'charge', angle: a2 };
  }

  // Keep pushing toward the pocket, but leave space for one answer.
  var go = norm(target.x - bx, target.y - by);
  var mx = go.x * 10, my = go.y * 10;

  // Small lateral wobble so we do not become a static line.
  var wob = (rand() - 0.5) * (mem.drift ? 10 : 6);
  mem.drift = mem.drift ? 0 : 1;
  mx += wob;
  my += wob * 0.5;

  // If the player is camping the corner, lean harder into the approach lane.
  if (inPocket) {
    mx += (px < 180 ? 6 : 2);
    my += (py > 700 ? 4 : 1);
  }

  return { type: 'move', dx: clamp(mx, -18, 18), dy: clamp(my, -18, 18) };
}

