export const meta = {
  name: 'Pocket Warden II',
  rationale: 'You camp the bottom-left pocket, so I keep the corner warm, but I only commit the full punish some of the time.',
  version: 2,
};

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

function dist2(ax, ay, bx, by) {
  const dx = ax - bx;
  const dy = ay - by;
  return dx * dx + dy * dy;
}

function pickHeatTarget(view) {
  const w = view.arena.w;
  const h = view.arena.h;
  let sx = 0, sy = 0, sw = 0;

  const heat = view.history && view.history.playerPosHeat;
  if (heat && heat.length) {
    for (let i = 0; i < heat.length; i++) {
      const wt = heat[i] || 0;
      if (!wt) continue;
      const cx = ((i % 8) + 0.5) * (w / 8);
      const cy = (Math.floor(i / 8) + 0.5) * (h / 8);
      sx += cx * wt;
      sy += cy * wt;
      sw += wt;
    }
  }

  if (sw > 0) return { x: sx / sw, y: sy / sw };
  return { x: 150, y: 730 };
}

function angleTo(ax, ay, bx, by) {
  return Math.atan2(by - ay, bx - ax);
}

export function init() {
  return {
    nextAttackAt: 0,
    nextSpawnAt: 90,
  };
}

export function decide(view, mem) {
  const t = view.tick | 0;
  const bx = view.boss.x;
  const by = view.boss.y;
  const px = view.player.x;
  const py = view.player.y;

  const target = pickHeatTarget(view);
  const d2 = dist2(bx, by, px, py);
  const close = d2 < 220 * 220;
  const mid = d2 < 360 * 360;

  // Occasionally seed pressure into the pocket they actually used.
  if (t >= mem.nextSpawnAt && view.boss.cooldowns.spawn <= 0 && rand() < 0.66) {
    mem.nextSpawnAt = t + 520 + ((rand() * 120) | 0);
    return {
      type: 'spawn',
      x: clamp(target.x + (rand() * 70 - 35), 20, 780),
      y: clamp(target.y + (rand() * 50 - 25), 20, 780),
    };
  }

  if (t >= mem.nextAttackAt) {
    const readyBurst = view.boss.cooldowns.burst <= 0;
    const readyCharge = view.boss.cooldowns.charge <= 0;
    const readySlam = view.boss.cooldowns.slam <= 0;

    // Only some corner approaches get the full ring.
    if ((close || (px < 300 && py > 600)) && readyBurst && rand() < 0.33) {
      mem.nextAttackAt = t + 50;
      return { type: 'burst', angle: angleTo(bx, by, px, py), count: 5 };
    }

    // Rare floor punish on the return path.
    if (readySlam && (close || (px < 280 && py > 620)) && rand() < 0.22) {
      mem.nextAttackAt = t + 72;
      return {
        type: 'slam',
        x: clamp(px + (rand() * 40 - 20), 40, 760),
        y: clamp(py + (rand() * 40 - 20), 40, 760),
      };
    }

    // A brief close-down, but not every time.
    if (mid && readyCharge && rand() < 0.25) {
      mem.nextAttackAt = t + 36;
      return { type: 'charge', angle: angleTo(bx, by, px, py) };
    }
  }

  // Gentle steering toward the hotspot, with long quiet beats.
  const dx = clamp(target.x - bx, -14, 14);
  const dy = clamp(target.y - by, -14, 14);

  if ((t & 11) !== 0) {
    return { type: 'move', dx, dy };
  }

  return { type: 'idle' };
}

