export const meta = {
  name: 'Warden I',
  rationale: 'You hide in the bottom-left pocket, so I press that corner with a little more force, then I still give you quiet beats to answer it.',
  version: 2,
};

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

function hypot2(dx, dy) {
  return Math.sqrt(dx * dx + dy * dy);
}

function norm(dx, dy) {
  const d = hypot2(dx, dy);
  if (!(d > 0)) return [0, 0];
  return [dx / d, dy / d];
}

function heatTarget(view) {
  const heat = view && view.history && view.history.playerPosHeat;
  let best = 56;
  let bestV = -1;
  if (heat && heat.length >= 64) {
    for (let i = 48; i < 64; i++) {
      const v = heat[i];
      if (v > bestV) {
        bestV = v;
        best = i;
      }
    }
  }
  const col = best % 8;
  const row = (best / 8) | 0;
  return { x: col * 100 + 50, y: row * 100 + 50 };
}

function angleTo(ax, ay, bx, by) {
  return Math.atan2(by - ay, bx - ax);
}

export function init() {
  return {
    lastAttack: -9999,
    nextSpawnAt: 90,
    nextPunchAt: 0,
  };
}

export function decide(view, mem) {
  const t = view.tick | 0;
  const bx = view.boss.x;
  const by = view.boss.y;
  const px = view.player.x;
  const py = view.player.y;

  const dx = px - bx;
  const dy = py - by;
  const dist = hypot2(dx, dy);

  const target = heatTarget(view);
  const tx = clamp(target.x, 60, 260);
  const ty = clamp(target.y, 620, 790);

  const readyBurst = view.boss.cooldowns.burst <= 0;
  const readyCharge = view.boss.cooldowns.charge <= 0;
  const readySlam = view.boss.cooldowns.slam <= 0;
  const readySpawn = view.boss.cooldowns.spawn <= 0;

  const quiet = t - (mem.lastAttack | 0);

  // Halfway between "never pressure" and "always pressure": occasional lane threat.
  if (readySpawn && t >= (mem.nextSpawnAt | 0) && rand() < 0.5) {
    mem.nextSpawnAt = t + 300 + ((rand() * 120) | 0);
    const sx = clamp(target.x + (rand() * 60 - 30), 20, 780);
    const sy = clamp(target.y + (rand() * 40 - 20), 20, 780);
    mem.lastAttack = t;
    return { type: 'spawn', x: sx, y: sy };
  }

  // Stay near the pocket they lived in, but don't sit on top of them.
  if (dist < 190) {
    const away = norm(bx - px, by - py);
    const mx = clamp(bx + away[0] * 34, 40, 760);
    const my = clamp(by + away[1] * 34, 40, 760);
    return { type: 'move', dx: mx - bx, dy: my - by };
  }

  // Signature punish, but only some approaches get the full answer.
  if (quiet >= 84) {
    const inPocket = px < 300 && py > 600;
    const midRange = dist > 190 && dist < 360;

    if (readyBurst && (inPocket || dist > 240) && rand() < 0.5) {
      mem.lastAttack = t;
      // Fewer full rings than the hard file: use the middle burst count.
      return { type: 'burst', angle: angleTo(bx, by, px, py), count: 5 };
    }

    if (readySlam && inPocket && rand() < 0.25) {
      mem.lastAttack = t;
      return {
        type: 'slam',
        x: clamp(px + (rand() * 40 - 20), 40, 760),
        y: clamp(py + (rand() * 40 - 20), 40, 760),
      };
    }

    if (readyCharge && midRange && rand() < 0.25) {
      mem.lastAttack = t;
      return { type: 'charge', angle: angleTo(bx, by, px, py) };
    }
  }

  // Gentle steering toward the hotspot, but not relentlessly.
  const moveX = tx - bx;
  const moveY = ty - by;

  if (Math.abs(moveX) + Math.abs(moveY) < 18) {
    return { type: 'idle' };
  }

  return { type: 'move', dx: moveX * 0.28, dy: moveY * 0.28 };
}
